import{_ as t,o as r,c as e,a3 as o}from"./chunks/framework.TInMeFlA.js";const n="/product-manual/chat-entry.png",l="/product-manual/chat-input.png",i="/product-manual/agent-entry.png",s="/product-manual/agent-manage.png",p="/product-manual/settings-entry.png",c="/product-manual/settings-general.png",d="/product-manual/settings-display.png",h="/product-manual/settings-directory.png",m="/product-manual/settings-memory.png",g="/product-manual/settings-shortcuts.png",u="/product-manual/settings-about.png",_="/product-manual/skills-market.png",b="/product-manual/skills-detail.png",k="/product-manual/skills-try.png",x="/product-manual/knowledge-base.png",f="/product-manual/knowledge-reference.png",T=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"Examples/jiaorong-agent/started.md","filePath":"Examples/jiaorong-agent/started.md","lastUpdated":null}'),q={name:"Examples/jiaorong-agent/started.md"};function P(A,a,I,w,S,y){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>交融超级智能体是一款为深度工作而生的桌面端 AI 助手，以“快速、专注、隐私优先”为核心设计理念，将 AI 能力融入日常工作流。</p><h2 id="产品简介" tabindex="-1">产品简介 <a class="header-anchor" href="#产品简介" aria-label="Permalink to &quot;产品简介&quot;">​</a></h2><ul><li><strong>极致效率，即刻响应</strong>：基于原生应用架构深度优化，指令交互零延迟。内置“深度工作专注模式”，智能屏蔽冗余干扰，帮助您聚焦核心任务。</li><li><strong>专业赋能，触手可及</strong>：拥有流畅的通用对话能力，贴合实际业务场景。支持一键生成 PPT、多文档智能分析、实时联网搜索等功能，让复杂操作化繁为简。</li><li><strong>安全可控，开放共赢</strong>：坚持隐私优先设计，支持本地数据处理与端侧加密，确保企业核心信息不外泄。同时，通过 MCP 协议无缝集成主流 AI 模型，并持续扩展技能生态。</li></ul><p>交融超级智能体不仅是工具，更是您深度思考与高效决策的可靠伙伴。</p><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><p>目前支持 Windows、Mac 及 Linux 版本，可按需下载安装：</p><ul><li><a href="https://c4ai.ccccltd.cn/xkprosdk/JiaorongAI-windows-x64.exe" target="_blank" rel="noreferrer">Windows x64</a></li><li><a href="https://c4ai.ccccltd.cn/xkprosdk/JiaorongAI-windows-arm64.exe" target="_blank" rel="noreferrer">Windows arm64</a></li><li><a href="https://c4ai.ccccltd.cn/xkprosdk/JiaorongAI-linux-x64.tar.gz" target="_blank" rel="noreferrer">Linux x64</a></li><li><a href="https://c4ai.ccccltd.cn/xkprosdk/JiaorongAI-mac-x64.dmg" target="_blank" rel="noreferrer">macOS x64</a></li><li><a href="https://c4ai.ccccltd.cn/xkprosdk/JiaorongAI-mac-arm64.dmg" target="_blank" rel="noreferrer">macOS arm64</a></li></ul><h2 id="产品使用" tabindex="-1">产品使用 <a class="header-anchor" href="#产品使用" aria-label="Permalink to &quot;产品使用&quot;">​</a></h2><h3 id="交融对话" tabindex="-1">交融对话 <a class="header-anchor" href="#交融对话" aria-label="Permalink to &quot;交融对话&quot;">​</a></h3><p>进入首页后，点击“交融对话”进入对话页：</p><p><img src="'+n+'" alt="交融对话入口"></p><p>在对话页，可以通过“选择项目”选择文件夹，通过 <code>@</code> 引用文件，通过 <code>/</code> 调起命令，通过 <code>+</code> 添加一个或多个附件：</p><p><img src="'+l+'" alt="交融对话输入能力"></p><h3 id="管理与新增-agent" tabindex="-1">管理与新增 Agent <a class="header-anchor" href="#管理与新增-agent" aria-label="Permalink to &quot;管理与新增 Agent&quot;">​</a></h3><p>在首页点击“管理 交融超级智能体 Agent”：</p><p><img src="'+i+'" alt="Agent 管理入口"></p><p>在管理页面，可以编辑及新增 Agent。编辑项包括名称、启用状态、描述、头像、系统提示词、内置工具的启用等：</p><p><img src="'+s+'" alt="Agent 管理页面"></p><h3 id="其他设置" tabindex="-1">其他设置 <a class="header-anchor" href="#其他设置" aria-label="Permalink to &quot;其他设置&quot;">​</a></h3><p>在对话页面，点击左下角的“设置”进入设置页面：</p><p><img src="'+p+'" alt="设置入口"></p><h4 id="通用设置" tabindex="-1">通用设置 <a class="header-anchor" href="#通用设置" aria-label="Permalink to &quot;通用设置&quot;">​</a></h4><p>可以设置文件最大大小、代理模式、开机时启动交融超级智能体等：</p><p><img src="'+c+'" alt="通用设置"></p><h4 id="显示设置" tabindex="-1">显示设置 <a class="header-anchor" href="#显示设置" aria-label="Permalink to &quot;显示设置&quot;">​</a></h4><p>可以设置语言、主题、系统通知、文字大小、字体、投屏保护、悬浮按钮等：</p><p><img src="'+d+'" alt="显示设置"></p><h4 id="目录环境" tabindex="-1">目录环境 <a class="header-anchor" href="#目录环境" aria-label="Permalink to &quot;目录环境&quot;">​</a></h4><p>可以查看对话使用过的项目目录，也支持直接打开及设为默认：</p><p><img src="'+h+'" alt="目录环境"></p><h4 id="记忆" tabindex="-1">记忆 <a class="header-anchor" href="#记忆" aria-label="Permalink to &quot;记忆&quot;">​</a></h4><p>支持查看、配置并管理每个 Agent 跨会话记住的内容。记忆按 Agent 隔离：</p><p><img src="'+m+'" alt="记忆设置"></p><h4 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h4><p>可以对“显示/隐藏窗口”、“新会话”、“聚焦搜索”、“切换侧边栏”等操作进行快捷键设置：</p><p><img src="'+g+'" alt="快捷键设置"></p><h4 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h4><p>可以查看当前版本，并执行“检查更新”。如有新版本发布，可在此安装下载：</p><p><img src="'+u+'" alt="关于与更新"></p><h3 id="技能中心" tabindex="-1">技能中心 <a class="header-anchor" href="#技能中心" aria-label="Permalink to &quot;技能中心&quot;">​</a></h3><h4 id="技能市场" tabindex="-1">技能市场 <a class="header-anchor" href="#技能市场" aria-label="Permalink to &quot;技能市场&quot;">​</a></h4><p>技能市场内置经营投标、工程建设、合约法务、综合办公、软件研发五大核心领域的实用技能，覆盖全业务链：</p><p><img src="'+_+'" alt="技能市场"></p><p>点击某一技能进入技能详情页：</p><p><img src="'+b+'" alt="技能详情"></p><p>点击“试一试”跳转至对话页，并附带相应话术：</p><p><img src="'+k+'" alt="技能试一试"></p><h4 id="新建技能" tabindex="-1">新建技能 <a class="header-anchor" href="#新建技能" aria-label="Permalink to &quot;新建技能&quot;">​</a></h4><p>支持两种方式新建技能，让专属技能随需而变：</p><ul><li><strong>通过对话直接生成</strong>：使用内置的“技能创建”技能，输入相关要求即可。</li><li><strong>上传文件快速定制</strong>：支持上传文件夹或 <code>.zip</code>，内容可包含一个或多个非嵌套技能目录；也可以上传单独的 <code>.md</code> 文件。系统并不能确保技能的可用性，请自行验证。</li></ul><h3 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h3><p>交融超级智能体已接入交融问之的知识库。点击左侧栏“知识库”进入页面，进行查看、编辑、提问等操作：</p><p><img src="'+x+'" alt="知识库"></p><p>也支持在对话中选择知识库的某个库、文件夹或文件进行引用，基于选择的内容进行总结、提问以及写作：</p><p><img src="'+f+'" alt="对话引用知识库"></p><h2 id="问题反馈" tabindex="-1">问题反馈 <a class="header-anchor" href="#问题反馈" aria-label="Permalink to &quot;问题反馈&quot;">​</a></h2><p>如果您在使用过程中有任何问题或修改建议，请在试用群中联系管理员，或者在 <a href="https://docs.qq.com/sheet/DWVNSZGhhUHBiSHRU?tab=BB08J2" target="_blank" rel="noreferrer">交融超级智能体反馈</a>中填写您的问题，我们会及时答复。</p>',58)])])}const B=t(q,[["render",P]]);export{T as __pageData,B as default};
